import { defaultExport, runtime } from '../../common/runtime';

/** Core components the pages build on, loaded through the registry: they live in core's lazy chunks. */
export let PageStructure;
export let IndexSidebar;
export async function loadCore() {
  if (PageStructure && IndexSidebar) return;
  const registry = runtime().reg;
  const [structure, sidebar] = await Promise.all([registry.asyncModuleImport('flarum/forum/components/PageStructure'), registry.asyncModuleImport('flarum/forum/components/IndexSidebar')]);
  PageStructure = defaultExport(structure);
  IndexSidebar = defaultExport(sidebar);
}
flarum.reg.add('ernestdefoe-glimpse', 'forum/ui/core', { PageStructure: PageStructure,IndexSidebar: IndexSidebar, });