export const AUDIENCE_ICONS = {
  everyone: 'fa-globe',
  members: 'fa-user-check',
  followers: 'fa-user-group'
};

/** A link's host, for the link button on a story ("example.com"). */
export function hostOf(url) {
  try {
    return new URL(url).hostname.replace(/^www\./, '');
  } catch (e) {
    return url;
  }
}

/** Starts fetching a photo before it is shown (videos are preloaded by an element in the viewer). */
export function preload(story) {
  if (story.kind() === 'photo' && story.mediaUrl()) {
    const img = new Image();
    img.decoding = 'async';
    img.src = story.mediaUrl();
  }
}
flarum.reg.add('ernestdefoe-glimpse', 'forum/ui/viewerTools', { AUDIENCE_ICONS: AUDIENCE_ICONS,hostOf: hostOf,preload: preload, });