import Component from 'flarum/common/Component';
import classList from 'flarum/common/utils/classList';
import { tx } from '../util';
import { replyChannel, sendReply } from './reply';
/**
 * The bottom of someone else's story: a field to reply privately (when Parley or Messages can carry it)
 * and the reaction button. The story pauses while the field has focus.
 */
export default class ReplyBar extends Component {
  text = '';
  view() {
    const {
      story
    } = this.attrs;
    const channel = replyChannel();
    if (!story.canReact() && !channel) return null;
    return m("div", {
      className: "GlimpseViewer-reply"
    }, channel ? this.field() : m("span", {
      className: "GlimpseViewer-spacer"
    }), story.canReact() ? m("button", {
      type: "button",
      className: classList('GlimpseViewer-react', story.myReaction() && 'is-active'),
      "aria-label": tx('viewer.react'),
      "aria-expanded": this.attrs.reacting ? 'true' : 'false',
      onclick: () => this.attrs.onreact()
    }, this.attrs.reaction) : null, channel && this.text.trim() ? m("button", {
      type: "button",
      className: "GlimpseViewer-send",
      "aria-label": tx('viewer.send'),
      onclick: () => this.send()
    }, m("i", {
      className: "fas fa-paper-plane",
      "aria-hidden": "true"
    })) : null);
  }
  field() {
    return m("input", {
      className: "GlimpseViewer-input",
      placeholder: tx('viewer.reply_placeholder', {
        name: this.attrs.name
      }),
      "aria-label": tx('viewer.reply_label'),
      maxlength: 500,
      value: this.text,
      onfocus: () => this.attrs.onpause(true),
      onblur: () => {
        if (!this.text) this.attrs.onpause(false);
      },
      oninput: e => {
        this.text = e.target.value;
      },
      onkeydown: e => {
        if (e.key === 'Enter') {
          e.preventDefault();
          this.send();
        }
      }
    });
  }
  send() {
    const text = this.text.trim();
    if (!text) return;
    this.text = '';
    document.activeElement?.blur();
    sendReply(this.attrs.story, text).then(() => this.attrs.onsay(tx('viewer.reply_sent', {
      name: this.attrs.name
    }))).catch(() => this.attrs.onsay(tx('viewer.reply_failed'))).finally(() => this.attrs.onpause(false));
  }
}
flarum.reg.add('ernestdefoe-glimpse', 'forum/ui/ReplyBar', ReplyBar);