import app from 'flarum/forum/app';
import Component from 'flarum/common/Component';
import Avatar from 'flarum/common/components/Avatar';
import Link from 'flarum/common/components/Link';
import classList from 'flarum/common/utils/classList';
import humanTime from 'flarum/common/helpers/humanTime';
import { failed, t, tx } from '../util';
import Gestures from './gestures';
import caption from './caption';
import ReplyBar from './ReplyBar';
import ViewerMenu from './ViewerMenu';
import { AUDIENCE_ICONS, hostOf, preload } from './viewerTools';
import { openSeenBy } from './modals';
const SEEN_FLUSH_MS = 1500;

/**
 * The full-screen story player. Touch and mouse are Gestures' job; keys here: ← → Space Esc. Photos and text stay up for the admin's
 * time, a video for its length (never past the admin's limit). The next story's media is fetched while
 * this one plays, and the next person's stories while their last one plays. Stories are marked seen in
 * batches, not one request each.
 */
export default class Viewer extends Component {
  users = [];
  userIndex = 0;
  stories = [];
  index = 0;
  loading = false;
  cache = new Map();
  elapsed = 0;
  duration = 6000;
  last = 0;
  raf = 0;
  paused = false;
  muted = true;
  menuOpen = false;
  reacting = false;
  toast = null;
  toastTimer = 0;
  seen = new Set();
  seenTimer = 0;
  gestures = new Gestures({
    card: () => this.element?.querySelector('.GlimpseViewer-card') ?? null,
    hold: on => this.setPaused(on),
    forward: () => this.next(),
    back: () => this.previous(),
    nextPerson: () => this.nextUser(),
    previousPerson: () => this.previousUser(),
    close: () => this.attrs.close()
  });
  previousFocus = null;
  keyHandler = e => this.onkey(e);
  oninit(vnode) {
    super.oninit(vnode);
    const {
      users,
      start,
      stories,
      startStory
    } = this.attrs.options;
    this.users = users;
    this.userIndex = Math.max(0, users.indexOf(start));
    if (stories) this.cache.set(start.id(), Promise.resolve(stories));
    this.loadUser(startStory);
  }
  oncreate(vnode) {
    super.oncreate(vnode);
    this.previousFocus = document.activeElement;
    document.addEventListener('keydown', this.keyHandler);
    document.body.classList.add('GlimpseViewer-open');
    vnode.dom.querySelector('.GlimpseViewer-close')?.focus();
    this.last = performance.now();
    this.raf = requestAnimationFrame(now => this.tick(now));
  }
  onremove(vnode) {
    super.onremove(vnode);
    cancelAnimationFrame(this.raf);
    clearTimeout(this.toastTimer);
    document.removeEventListener('keydown', this.keyHandler);
    document.body.classList.remove('GlimpseViewer-open');
    this.flushSeen();
    this.previousFocus?.focus?.();
  }

  // ---------- data ----------

  user() {
    return this.users[this.userIndex];
  }
  story() {
    return this.stories[this.index];
  }
  storiesOf(user) {
    const id = user.id();
    if (!this.cache.has(id)) {
      this.cache.set(id, app.store.find('stories', {
        filter: {
          author: id,
          live: '1'
        },
        sort: 'createdAt',
        page: {
          limit: 100,
          total: 0
        }
      }).then(stories => [...stories]).catch(() => {
        failed();
        return [];
      }));
    }
    return this.cache.get(id);
  }
  loadUser(startStory, fromEnd = false) {
    const user = this.user();
    if (!user) return this.attrs.close();
    this.loading = true;
    this.storiesOf(user).then(stories => {
      if (this.user() !== user) return;
      this.loading = false;
      if (!stories.length) {
        // Gone (expired, deleted) since the bar was drawn: on to the next person.
        this.users.splice(this.userIndex, 1);
        if (!this.users.length) return this.attrs.close();
        this.userIndex = Math.min(this.userIndex, this.users.length - 1);
        return this.loadUser();
      }
      this.stories = stories;
      const firstUnseen = stories.findIndex(story => !story.isSeen());
      this.index = startStory ? Math.max(0, stories.indexOf(startStory)) : fromEnd ? stories.length - 1 : Math.max(0, firstUnseen);
      this.begin();
      m.redraw();
    });
  }
  begin() {
    const story = this.story();
    if (!story) return;
    this.elapsed = 0;
    this.last = performance.now();
    this.menuOpen = false;
    this.reacting = false;
    this.paused = false;
    const slide = (Number(app.forum.attribute('glimpseSlideSeconds')) || 6) * 1000;
    const max = (Number(app.forum.attribute('glimpseVideoMaxSeconds')) || 15) * 1000;
    this.duration = story.kind() === 'video' ? Math.min(story.durationMs() || max, max) : slide;
    this.markSeen(story);
    this.prefetch();
  }
  prefetch() {
    const next = this.stories[this.index + 1];
    if (next) return preload(next);
    const nextUser = this.users[this.userIndex + 1];
    if (nextUser) this.storiesOf(nextUser).then(stories => stories[0] && preload(stories[0]));
  }
  markSeen(story) {
    if (story.isSeen() || story.user() === app.session.user || !app.session.user) return;
    story.pushAttributes({
      isSeen: true
    });
    this.seen.add(story.id());
    clearTimeout(this.seenTimer);
    this.seenTimer = window.setTimeout(() => this.flushSeen(), SEEN_FLUSH_MS);
  }
  flushSeen() {
    clearTimeout(this.seenTimer);
    if (!this.seen.size) return;
    const ids = [...this.seen].map(Number);
    this.seen.clear();
    // Didn't go through: keep them for the next flush (closing the viewer flushes once more).
    app.request({
      method: 'POST',
      url: `${app.forum.attribute('apiUrl')}/stories/seen`,
      body: {
        ids
      },
      errorHandler: () => {}
    }).catch(() => ids.forEach(id => this.seen.add(String(id))));
  }

  // ---------- playback ----------

  tick(now) {
    const video = this.video();
    if (!this.paused && !this.loading && this.story()) {
      if (video && video.duration && isFinite(video.duration)) {
        this.duration = Math.min(video.duration * 1000, (Number(app.forum.attribute('glimpseVideoMaxSeconds')) || 15) * 1000);
        this.elapsed = video.currentTime * 1000;
      } else if (!video) {
        this.elapsed += now - this.last;
      }
      const bar = this.element?.querySelector('.GlimpseViewer-progress li.is-current b');
      if (bar) bar.style.width = `${Math.min(100, this.elapsed / this.duration * 100)}%`;
      if (this.elapsed >= this.duration) this.next();
    }
    this.last = now;
    this.raf = requestAnimationFrame(time => this.tick(time));
  }
  video() {
    return this.element?.querySelector('.GlimpseViewer-media video') ?? null;
  }
  setPaused(paused) {
    this.paused = paused;
    this.last = performance.now();
    const video = this.video();
    if (video && paused) video.pause();
    if (video && !paused) {
      // A browser that won't autoplay leaves the story paused, with the play button showing.
      video.play().catch(() => {
        this.paused = true;
        m.redraw();
      });
    }
    m.redraw();
  }
  next() {
    if (this.index < this.stories.length - 1) {
      this.index++;
      this.begin();
      m.redraw();
    } else this.nextUser();
  }
  previous() {
    if (this.index > 0) {
      this.index--;
      this.begin();
      m.redraw();
    } else if (this.userIndex > 0) {
      this.userIndex--;
      this.loadUser(undefined, true);
    } else {
      this.begin();
    }
  }
  nextUser() {
    this.flushSeen();
    if (this.userIndex < this.users.length - 1) {
      this.userIndex++;
      this.loadUser();
    } else this.attrs.close();
  }
  previousUser() {
    if (this.userIndex > 0) {
      this.userIndex--;
      this.loadUser();
    } else {
      this.index = 0;
      this.begin();
    }
  }

  // ---------- input ----------

  onkey(e) {
    // Typing a reply, or a modal on top: the keys are theirs.
    const target = e.target;
    if (target?.closest('input, textarea, .ModalManager')) return;
    if (e.key === 'ArrowRight') {
      e.preventDefault();
      this.next();
    } else if (e.key === 'ArrowLeft') {
      e.preventDefault();
      this.previous();
    } else if (e.key === ' ') {
      e.preventDefault();
      this.setPaused(!this.paused);
    } else if (e.key === 'Escape') {
      e.preventDefault();
      if (this.menuOpen) {
        this.menuOpen = false;
        this.setPaused(false);
      } else this.attrs.close();
    }
  }
  say(message) {
    this.toast = message;
    clearTimeout(this.toastTimer);
    this.toastTimer = window.setTimeout(() => {
      this.toast = null;
      m.redraw();
    }, 1800);
    m.redraw();
  }

  // ---------- actions ----------

  react(reaction) {
    const story = this.story();
    if (!story) return;
    this.reacting = false;
    const previous = story.myReaction();
    story.pushAttributes({
      myReaction: reaction
    });
    app.request({
      method: 'POST',
      url: `${app.forum.attribute('apiUrl')}/stories/${story.id()}/reaction`,
      body: {
        reaction
      }
    }).then(payload => {
      app.store.pushPayload(payload);
      this.say(reaction ? tx('viewer.reacted', {
        reaction
      }) : tx('viewer.unreacted'));
    }).catch(() => story.pushAttributes({
      myReaction: previous
    })).finally(() => this.setPaused(false));
  }

  // ---------- view ----------

  view() {
    const story = this.story();
    const user = this.user();
    return m("div", {
      className: classList('GlimpseViewer', this.paused && 'is-paused', this.gestures.holding && 'is-holding'),
      role: "dialog",
      "aria-modal": "true",
      "aria-label": tx('viewer.label', {
        name: user?.displayName() || ''
      })
    }, m("button", {
      type: "button",
      className: "GlimpseViewer-close",
      "aria-label": tx('viewer.close'),
      onclick: () => this.attrs.close()
    }, m("i", {
      className: "fas fa-xmark",
      "aria-hidden": "true"
    })), m("button", {
      type: "button",
      className: "GlimpseViewer-arrow GlimpseViewer-arrow--prev",
      "aria-label": tx('viewer.previous'),
      onclick: () => this.previous()
    }, m("i", {
      className: "fas fa-chevron-left",
      "aria-hidden": "true"
    })), this.card(story, user), m("button", {
      type: "button",
      className: "GlimpseViewer-arrow GlimpseViewer-arrow--next",
      "aria-label": tx('viewer.next'),
      onclick: () => this.next()
    }, m("i", {
      className: "fas fa-chevron-right",
      "aria-hidden": "true"
    })));
  }
  card(story, user) {
    const own = !!story && story.user() === app.session.user;
    return m("div", {
      className: "GlimpseViewer-card",
      onpointerdown: e => this.gestures.down(e),
      onpointermove: e => this.gestures.move(e),
      onpointerup: e => this.gestures.up(e),
      onpointercancel: () => this.gestures.cancel(),
      oncontextmenu: e => e.preventDefault()
    }, story ? this.media(story) : m("div", {
      className: "GlimpseViewer-media GlimpseViewer-media--loading"
    }), m("ol", {
      className: "GlimpseViewer-progress",
      "aria-hidden": "true"
    }, this.stories.map((_, i) => m("li", {
      className: classList(i < this.index && 'is-done', i === this.index && 'is-current')
    }, m("b", null)))), story && user ? this.header(story, user, own) : null, this.menuOpen && story ? m(ViewerMenu, {
      story: story,
      own: own,
      onsay: message => this.say(message),
      onclose: resume => {
        this.menuOpen = false;
        if (resume) this.setPaused(false);
      },
      onmuted: () => this.nextUser(),
      ondeleted: () => this.dropCurrent()
    }) : null, this.paused && this.gestures.holding ? m("div", {
      className: "GlimpseViewer-paused"
    }, t('viewer.paused')) : null, this.toast ? m("div", {
      className: "GlimpseViewer-toast",
      role: "status"
    }, this.toast) : null, story ? this.footer(story, user, own) : null, this.nextPreload());
  }
  header(story, user, own) {
    return m("header", {
      className: "GlimpseViewer-head"
    }, m(Link, {
      href: app.route.user(user),
      className: "GlimpseViewer-author",
      onclick: () => this.attrs.close()
    }, m(Avatar, {
      user: user
    }), m("span", {
      className: "GlimpseViewer-name"
    }, own ? t('viewer.your_story') : user.displayName())), m("span", {
      className: "GlimpseViewer-time"
    }, this.attrs.options.label || humanTime(story.createdAt())), m("i", {
      className: classList('GlimpseViewer-audience fas', AUDIENCE_ICONS[story.audience()]),
      title: tx(`audience.${story.audience()}`),
      "aria-label": tx(`audience.${story.audience()}`)
    }), m("span", {
      className: "GlimpseViewer-spacer"
    }), story.kind() === 'video' ? m("button", {
      type: "button",
      className: "GlimpseViewer-icon",
      "aria-label": tx(this.muted ? 'viewer.unmute' : 'viewer.mute'),
      onclick: () => this.toggleSound()
    }, m("i", {
      className: classList('fas', this.muted ? 'fa-volume-xmark' : 'fa-volume-high'),
      "aria-hidden": "true"
    })) : null, m("button", {
      type: "button",
      className: "GlimpseViewer-icon",
      "aria-label": tx(this.paused ? 'viewer.play' : 'viewer.pause'),
      onclick: () => this.setPaused(!this.paused)
    }, m("i", {
      className: classList('fas', this.paused ? 'fa-play' : 'fa-pause'),
      "aria-hidden": "true"
    })), m("button", {
      type: "button",
      className: "GlimpseViewer-icon",
      "aria-label": tx('viewer.more'),
      "aria-expanded": this.menuOpen ? 'true' : 'false',
      onclick: () => {
        this.menuOpen = !this.menuOpen;
        this.setPaused(this.menuOpen);
      }
    }, m("i", {
      className: "fas fa-ellipsis",
      "aria-hidden": "true"
    })));
  }
  footer(story, user, own) {
    return m("footer", {
      className: "GlimpseViewer-foot"
    }, story.caption() ? m("p", {
      className: "GlimpseViewer-caption"
    }, caption(story)) : null, story.linkUrl() ? m("a", {
      className: "GlimpseViewer-link",
      href: story.linkUrl(),
      target: "_blank",
      rel: "nofollow ugc noopener noreferrer"
    }, m("i", {
      className: "fas fa-link",
      "aria-hidden": "true"
    }), " ", hostOf(story.linkUrl())) : null, this.reacting ? this.reactionPicker(story) : null, own ? m("button", {
      type: "button",
      className: "GlimpseViewer-seen",
      onclick: () => this.openSeenBy(story)
    }, m("i", {
      className: "fas fa-eye",
      "aria-hidden": "true"
    }), " ", t('viewer.seen_by', {
      count: story.viewCount() || 0
    }), story.reactionCount() ? m("span", {
      className: "GlimpseViewer-seenReactions"
    }, " \xB7 ", t('viewer.reactions', {
      count: story.reactionCount()
    })) : null) : this.replyRow(story, user));
  }

  /** The reply field (when replies have somewhere to go) and the reaction button. */
  replyRow(story, user) {
    const reactions = this.reactions();
    return m(ReplyBar, {
      story: story,
      name: user?.displayName() || '',
      reaction: story.myReaction() || reactions[0],
      reacting: this.reacting,
      onpause: paused => this.setPaused(paused),
      onsay: message => this.say(message),
      onreact: () => {
        if (reactions.length === 1) return this.react(story.myReaction() ? null : reactions[0]);
        this.reacting = !this.reacting;
        this.setPaused(this.reacting);
      }
    });
  }
  reactionPicker(story) {
    return m("div", {
      className: "GlimpseViewer-reactions",
      role: "group",
      "aria-label": tx('viewer.react')
    }, this.reactions().map(reaction => m("button", {
      type: "button",
      className: classList(story.myReaction() === reaction && 'is-active'),
      "aria-pressed": story.myReaction() === reaction ? 'true' : 'false',
      onclick: () => this.react(story.myReaction() === reaction ? null : reaction)
    }, reaction)));
  }
  reactions() {
    const list = app.forum.attribute('glimpseReactions');
    return list?.length ? list : ['❤️'];
  }
  media(story) {
    if (story.kind() === 'text') {
      const text = story.text() || '';
      return m("div", {
        className: classList('GlimpseViewer-media GlimpseText', `GlimpseBg-${story.background() ?? 0}`)
      }, m("p", {
        className: classList('GlimpseText-body', text.length > 90 && 'is-long')
      }, text));
    }
    return m("div", {
      className: "GlimpseViewer-media"
    }, story.kind() === 'video' ? m("video", {
      key: story.id(),
      src: story.mediaUrl(),
      autoplay: true,
      playsinline: true,
      muted: this.muted,
      preload: "auto",
      onended: () => this.next(),
      onloadeddata: e => {
        if (this.paused) e.target.pause();
      }
    }) : m("img", {
      key: story.id(),
      src: story.mediaUrl(),
      alt: story.caption() || tx('viewer.photo_alt', {
        name: (story.user() || null)?.displayName()
      }),
      draggable: false
    }));
  }

  /** The next story's media, fetched while this one plays. */
  nextPreload() {
    const next = this.stories[this.index + 1];
    if (!next || next.kind() !== 'video' || !next.mediaUrl()) return null;
    return m("video", {
      className: "GlimpseViewer-preload",
      src: next.mediaUrl(),
      preload: "auto",
      muted: true,
      playsinline: true,
      "aria-hidden": "true"
    });
  }

  /** The current story was deleted: on to the next one, or the next person. */
  dropCurrent() {
    const user = this.user();
    this.stories.splice(this.index, 1);
    if (user) this.cache.delete(user.id());
    if (!this.stories.length) return this.nextUser();
    this.index = Math.min(this.index, this.stories.length - 1);
    this.begin();
  }
  toggleSound() {
    this.muted = !this.muted;
    const video = this.video();
    if (video) video.muted = this.muted;
  }
  openSeenBy(story) {
    this.setPaused(true);
    openSeenBy(story, () => this.setPaused(false));
  }
}
flarum.reg.add('ernestdefoe-glimpse', 'forum/ui/Viewer', Viewer);